    for(const entry of tree.tree||[]){if(entry.type!=='blob'||entry.path.endsWith('/.gitkeep'))continue;const parts=entry.path.split('/');if(parts[0]==='content-studio'&&['drafts','completed'].includes(parts[1])&&entry.path.endsWith('.json')){draftFiles.push(entry);continue}const folder=folders.find(item=>item.name===parts[0]);if(!folder)continue;if(parts[0]==='official-photos'&&parts.length>=4&&parts[2]==='thumbnails')continue;const name=parts[parts.length-1],encodedPath=entry.path.split('/').map(encodeURIComponent).join('/'),subfolder=parts.length>2?parts[1]:'';const thumbPath=parts[0]==='official-photos'?photoThumbnails.get(`${subfolder}/${name}`):null;const thumbnailUrl=thumbPath?`https://raw.githubusercontent.com/${githubRepository}/main/${thumbPath.split('/').map(encodeURIComponent).join('/')}?_=${Date.now()}`:null;folder.files.push({name,path:entry.path,sha:entry.sha,url:`https://raw.githubusercontent.com/${githubRepository}/main/${encodedPath}?_=${Date.now()}`,thumbnailUrl,subfolder,type:mediaType(name),size:entry.size})}
